def _schedule_next_run_tz(
    self,
    interval: int,
    at_time: datetime.time,
    tz,
) -> None:
    """
    Compute next_run for a timezone-aware job.

    All calculations are performed in the target timezone so that
    DST transitions and non-whole-hour offsets are handled correctly.
    The final result is returned as a naive datetime in the local
    system timezone.
    """
    import pytz

    now_local = datetime.datetime.now()

    # Determine the local timezone (the system TZ, handling DST).
    local_tz = now_local.astimezone().tzinfo

    # Convert now to the target timezone as an aware datetime.
    now_aware_local = datetime.datetime(
        now_local.year,
        now_local.month,
        now_local.day,
        now_local.hour,
        now_local.minute,
        now_local.second,
        tzinfo=local_tz,
    )
    now_utc = now_aware_local.astimezone(pytz.UTC)
    now_target = now_utc.astimezone(tz)

    # Build a candidate datetime in the target timezone.
    candidate = self._build_candidate_in_tz(
        now_target, at_time, interval
    )

    # Handle DST transitions for the candidate.
    try:
        candidate_aware = tz.localize(candidate, is_dst=None)
    except pytz.exceptions.NonExistentTimeError:
        # The wall-clock time falls in a DST gap (spring forward).
        # Return the first valid moment *after* the gap.
        dt_fallback = tz.localize(candidate, is_dst=False)
        gap_start = self._gap_start_for_unit(candidate, at_time)
        offset_into_gap = candidate - gap_start
        transition_utc = dt_fallback - offset_into_gap
        candidate_aware = transition_utc.astimezone(tz)
        # If the adjusted time is still before now_target, advance by one period.
        if candidate_aware <= now_target:
            candidate_aware += self._period_for_unit()
    except pytz.exceptions.AmbiguousTimeError:
        # The wall-clock time occurs twice (fall back). Use the first
        # occurrence (before the clock moves backward).
        candidate_aware = tz.localize(candidate, is_dst=True)

    # Convert back to local time (naive).
    next_utc = candidate_aware.astimezone(pytz.UTC)
    next_local = next_utc.astimezone(local_tz)
    self.next_run = next_local.replace(tzinfo=None)

