def _gap_start_for_unit(
    self, candidate: datetime.datetime, at_time: datetime.time
) -> datetime.datetime:
    """
    Compute the start of the DST gap for the given unit and candidate time.
    """
    if self.unit == "hours":
        return candidate.replace(minute=at_time.minute, second=at_time.second, microsecond=0)
    elif self.unit == "minutes":
        return candidate.replace(second=at_time.second, microsecond=0)
    else:
        return candidate.replace(minute=0, second=0, microsecond=0)

